export function getCountyBySlug(slug) {
  return counties.find(c => c.slug === slug) || null;
}

export function getCountiesByState(stateCode) {
  return counties.filter(c => c.code === stateCode);
}

// Returns Next.js getStaticPaths format: [{ params: { slug } }, ...]
export function getAllCountySlugs() {
  return counties.map(c => ({ params: { slug: c.slug } }));
}
